<?php
namespace App\Controllers;
use App\Models\GuideModel;use App\Models\GuideCategoryModel;use App\Models\ProductModel;use App\Models\ProductPackageModel;use App\Services\StorefrontService;use App\Services\GuideContentService;use CodeIgniter\Exceptions\PageNotFoundException;
class GuideController extends BaseController {
 public function index(){return $this->listing();}public function search(){return $this->listing(null,true);}public function category(string $slug){$category=(new GuideCategoryModel())->where(['slug'=>$slug,'status'=>'active'])->first();if(!$category)throw PageNotFoundException::forPageNotFound();return $this->listing($category);}
 private function listing(?array $category=null,bool $search=false){$m=(new GuideModel())->published();$q=$search?trim((string)$this->request->getGet('q')):'';if($category){$ids=[$category['id']];foreach((new GuideCategoryModel())->where('parent_id',$category['id'])->where('status','active')->findAll() as $child)$ids[]=$child['id'];$m->whereIn('category_id',$ids);}if($q)$m->groupStart()->like('title',$q)->orLike('excerpt',$q)->groupEnd();$rows=$m->orderBy('featured','DESC')->orderBy('published_at','DESC')->paginate(12);$store=new StorefrontService();return view('frontend/guides/index',['title'=>$search?'গাইড খুঁজুন':($category?($category['seo_title']?:$category['name']):'Gardening Guides'),'metaDescription'=>$category?($category['seo_description']?:$category['description']):'বাগান করার সহজ গাইড','canonical'=>$search?url_to('guides.search'):($category?url_to('guides.category',$category['slug']):url_to('guides.index')),'robots'=>$search?'noindex,follow':null,'rows'=>$rows,'pager'=>$m->pager,'categories'=>(new GuideCategoryModel())->where('status','active')->orderBy('sort_order')->findAll(),'category'=>$category,'q'=>$q,'search'=>$search,'settings'=>$store->settings()]);}
 public function show(string $slug){$m=new GuideModel();$guide=$m->published()->where('guides.slug',$slug)->first();if(!$guide)throw PageNotFoundException::forPageNotFound();$category=$guide['category_id']?(new GuideCategoryModel())->where(['id'=>$guide['category_id'],'status'=>'active'])->first():null;$db=db_connect();$products=$db->table('guide_products gp')->select('p.*')->join('products p','p.id=gp.product_id')->where('gp.guide_id',$guide['id'])->where('p.status','active')->where('p.deleted_at',null)->get()->getResultArray();$packages=$db->table('guide_packages gp')->select('p.*')->join('product_packages p','p.id=gp.package_id')->where('gp.guide_id',$guide['id'])->where('p.status','active')->where('p.deleted_at',null)->get()->getResultArray();$faqs=$db->table('guide_faqs')->where('guide_id',$guide['id'])->orderBy('sort_order')->get()->getResultArray();[$content,$toc]=(new GuideContentService())->outline($guide['content']);$related=(new GuideModel())->published()->where('id !=',$guide['id']);if($guide['category_id'])$related->where('category_id',$guide['category_id']);$related=$related->orderBy('published_at','DESC')->findAll(3);$latest=(new GuideModel())->published()->where('id !=',$guide['id'])->orderBy('published_at','DESC')->findAll(4);$latestIds=array_column($latest,'id');$popularModel=(new GuideModel())->published()->where('id !=',$guide['id']);if($latestIds)$popularModel->whereNotIn('id',$latestIds);$popular=$popularModel->orderBy('views','DESC')->orderBy('published_at','DESC')->findAll(4);$guideCategories=(new GuideCategoryModel())->where('status','active')->orderBy('sort_order')->findAll();$categoryCounts=[];foreach($db->table('guides')->select('category_id, COUNT(*) AS total')->whereIn('status',['published','scheduled'])->where('published_at <=',date('Y-m-d H:i:s'))->groupBy('category_id')->get()->getResultArray() as $countRow)$categoryCounts[$countRow['category_id']]=(int)$countRow['total'];$db->table('guides')->where('id',$guide['id'])->set('views','views+1',false)->update();$store=new StorefrontService();return view('frontend/guides/show',['title'=>$guide['seo_title']?:$guide['title'],'metaDescription'=>$guide['seo_description']?:$guide['excerpt'],'canonical'=>url_to('guides.show',$slug),'ogImage'=>$guide['featured_image'],'ogType'=>'article','guide'=>$guide,'category'=>$category,'content'=>$content,'toc'=>$toc,'faqs'=>$faqs,'products'=>$store->decorateProducts($products),'packages'=>$store->decoratePackages($packages),'related'=>$related,'latest'=>$latest,'popular'=>$popular,'guideCategories'=>$guideCategories,'categoryCounts'=>$categoryCounts,'settings'=>$store->settings()]);}
 public function sitemap(){ $urls=[['loc'=>url_to('store.home')],['loc'=>url_to('catalog.products')],['loc'=>url_to('catalog.packages')],['loc'=>url_to('guides.index')]];foreach((new \App\Models\ProductCategoryModel())->where('status','active')->findAll() as $row)$urls[]=['loc'=>url_to('catalog.category',$row['slug']),'lastmod'=>substr($row['updated_at']??'',0,10)];foreach((new ProductModel())->where('status','active')->findAll() as $row)$urls[]=['loc'=>url_to('catalog.product',$row['slug']),'lastmod'=>substr($row['updated_at']??'',0,10)];foreach((new ProductPackageModel())->where('status','active')->findAll() as $row)$urls[]=['loc'=>url_to('catalog.package',$row['slug']),'lastmod'=>substr($row['updated_at']??'',0,10)];foreach((new GuideCategoryModel())->where('status','active')->findAll() as $row)$urls[]=['loc'=>url_to('guides.category',$row['slug']),'lastmod'=>substr($row['updated_at']??'',0,10)];foreach((new GuideModel())->published()->findAll() as $row)$urls[]=['loc'=>url_to('guides.show',$row['slug']),'lastmod'=>substr($row['updated_at']??'',0,10)];$xml='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';foreach($urls as $row){$xml.='<url><loc>'.htmlspecialchars($row['loc'],ENT_XML1|ENT_QUOTES,'UTF-8').'</loc>';if(!empty($row['lastmod']))$xml.='<lastmod>'.$row['lastmod'].'</lastmod>';$xml.='</url>';}$xml.='</urlset>';return $this->response->setContentType('application/xml')->setBody($xml);}
}
